import { reactive } from 'react';

interface TicTacToeState {
  moves: number[];
}

const TicTacToe = () => {
  const [moves, setMoves] = reactive<number[]>([]);

  const getMoves = () => {
    return [...Array(3)].map((_, colIndex) =>
      Array(3)
        .fill()
        .map((_, rowIndex) => rowIndex + (colIndex % 2 === 0 ? 'X' : 'O'))
    );
  };

  const movePlayer = (row: number, column: number) => {
    if (moves.includes(row * 3 + column)) return;
    moves.push(row * 3 + column);
    setMoves(moves);
  };

  return (
    <div>
      <p>Actions</p>
      <ul>
        {getMoves().map((row, rowIndex) => (
          <li key={rowIndex}>
            {row.map((col, colIndex) => {
              return (
                <button
                  onClick={() => movePlayer(rowIndex, colIndex)}
                  style={{ cursor: 'pointer', border: '1px solid black' }}
                >
                  {col === 'O' ? 'O' : 'X'}
                </button>
              );
            })}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default TicTacToe;
